def shift_digits_in_string(s, k):
    result = []
    digits = '0123456789'
    for c in s:
        if c in digits:
            d = (int(c) + k) % 10
            result.append(str(d))
        else:
            result.append(c)
    return ''.join(result)

def mask_digits(s, mask_char):
    digits = '0123456789'
    return ''.join(mask_char if c in digits else c for c in s)

def replace_vowels_with_symbol(s, symbol):
    vowels = set('aeiouAEIOU')
    return ''.join(symbol if c in vowels else c for c in s)

def remove_duplicate_adjacent_chars(s):
    if not s:
        return ''
    result = [s[0]]
    for c in s[1:]:
        if c != result[-1]:
            result.append(c)
    return ''.join(result)

def alternate_upper_lower(s):
    result = []
    upper_turn = True
    for c in s:
        if c.isalpha():
            if upper_turn:
                result.append(c.upper())
            else:
                result.append(c.lower())
            upper_turn = not upper_turn
        else:
            result.append(c)
    return ''.join(result)

def toggle_case_at_indices(s, indices):
    idx_set = set(i for i in indices if 0 <= i < len(s))
    result = list(s)
    for i in idx_set:
        result[i] = result[i].swapcase()
    return ''.join(result)

def capitalize_after_delimiter(s, delim):
    result = list(s)
    for i, c in enumerate(s):
        if c == delim and i + 1 < len(s) and s[i + 1].isalpha():
            result[i + 1] = s[i + 1].upper()
    return ''.join(result)

def is_alternating_case(s):
    letters = [c for c in s if c.isalpha()]
    for i in range(1, len(letters)):
        if letters[i].isupper() == letters[i - 1].isupper():
            return False
    return True

def is_alternating_parity_digits(s):
    for i in range(1, len(s)):
        if int(s[i]) % 2 == int(s[i - 1]) % 2:
            return False
    return True

def has_alternating_vowel_consonant(s):
    vowels = set('aeiou')
    letters = [c.lower() for c in s if c.isalpha()]

    def is_vowel(c):
        return c in vowels

    for i in range(1, len(letters)):
        if is_vowel(letters[i]) == is_vowel(letters[i - 1]):
            return False
    return True

def compress_runs_min_length(s, min_run):
    if not s:
        return ''
    result = []
    i = 0
    n = len(s)
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        run_len = j - i
        if run_len >= min_run:
            result.append(s[i] + str(run_len))
        else:
            result.append(s[i] * run_len)
        i = j
    return ''.join(result)

def compress_to_tuples(s):
    if not s:
        return []
    result = []
    i = 0
    n = len(s)
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        result.append((s[i], j - i))
        i = j
    return result

def count_runs(s):
    if not s:
        return 0
    count = 1
    for i in range(1, len(s)):
        if s[i] != s[i - 1]:
            count += 1
    return count

def split_on_multiple_delimiters(s, delims):
    delim_set = set(delims)
    tokens = []
    current = []
    for c in s:
        if c in delim_set:
            if current:
                tokens.append(''.join(current))
                current = []
        else:
            current.append(c)
    if current:
        tokens.append(''.join(current))
    return tokens
